-- The two checklists published on 2026-11-18: Having People Over Without the
-- Dread (Hosting) and After You Make a Mistake at Work (Mistakes).
-- Generated by `python3 tools/checklists_sql.py having-people-over-without-the-dread
-- after-you-make-a-mistake-at-work`; the repo copy in data/checklists.json is
-- the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('having-people-over-without-the-dread', 'Having People Over Without the Dread', 'Open this in the days before people come to your home, when the idea of hosting is already costing you more than the evening will. It helps you plan a version you can actually enjoy and gives you permission to keep it small.', 'Hosting', '["Decide the end time before you invite — Knowing when it finishes makes the whole evening easier to say yes to.", "Pick one thing to cook, not three — A simple meal leaves you energy for the people in front of you.", "Clean only the rooms people will see — Nobody is inspecting the closets, and the rest can wait.", "Ask someone to bring a dish — Letting guests help makes them comfortable and takes a job off your list.", "Set the first drinks out before they arrive — A little staging means you are not working the first ten minutes.", "Plan one quiet five minutes for yourself — Stepping into another room mid-evening resets you without ending anything.", "Let the house be imperfect on purpose — Guests relax faster in a home that looks lived in than one that looks staged.", "Leave the dishes until morning — The evening is what you invited them for, and the kitchen can keep."]'::jsonb, 'as needed', array['Social Anxiety', 'Boundaries', 'Self-Care']::text[], 1, '2026-11-18T16:00:00+00:00'::timestamptz),
  ('after-you-make-a-mistake-at-work', 'After You Make a Mistake at Work', 'Open this in the hour after you realize you got something wrong at work, when your stomach has dropped and you want to hide. It helps you tell the right person, fix what can be fixed, and stop the replay from taking over your week.', 'Mistakes', '["Write down what happened in plain order — Facts on paper are smaller and clearer than the version in your head.", "Tell the person who needs to know first — Bad news travels better from you than from someone else.", "Say what you are doing about it — A mistake plus a plan is a very different conversation.", "Repair the part that can still be repaired — Acting on the fixable piece takes the helpless feeling out of it.", "Keep the error apart from your worth — You did something wrong, which is not the same as being no good at this.", "Note the one step that would have caught it — A single check added is worth more than an hour of self-blame.", "Set a time to stop thinking about it — A limit on the replay keeps one afternoon from becoming a week.", "Tell someone outside work how it felt — Saying it out loud to a friend takes the shame out of the room."]'::jsonb, 'as needed', array['Work', 'Shame', 'Self-Compassion']::text[], 1, '2026-11-18T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
